import type { AudioSource } from 'expo-audio';

// Bundled dialogue audio, keyed by "<dialogueId>:<turnIndex>" (e.g. "es-cafe:0").
// Generated by scripts/tts/generate_dialogues.py (Chatterbox, per-speaker
// cloning). When empty, dialogue turns fall back to on-device TTS.
export const dialogueAudio: Record<string, AudioSource> = {};

export function getDialogueAudioAsset(key: string): AudioSource | undefined {
  return dialogueAudio[key];
}
